head.script:
// https://inswave01.atlassian.net/browse/WAEA-1375



// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[column > P > invalidMessageFunc]<br/>inputType='calendar' 인 Column 에서 입력값의 유효성 검증이 실패했을때 처리하기 위한 사용자 정의 함수를 설정합니다.",
    "validation" : [
        "Column 의 dateValidCheck=true 이거나 dateValidSet=true 인 경우에 동작합니다.",
        "사용자 정의 함수의 반환값이 새로운 오류 메시지로 적용됩니다.",
        "사용자 정의 함수에서 값을 반환하지 않거나 빈 문자열('') 을 반환하면 메시지가 표시되지 않습니다.",
        "사용자 정의 함수에서 반환된 값은 alert() 메소드로 표시됩니다.",
        "invalidMessageFunc 속성 설정 시 유효하지 않은 날짜/시간이 입력되면 시스템 기본 오류 메시지가 표시되지 않습니다.",
    ]
}

// 사용자 정의 함수가 반환하는 오류 메시지
scwin.returnMessage = "유효하지 않은 날짜입니다. 다시 입력하세요.";



scwin.onpageload = async function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // validation 2, 4, 5 : 엔진이 표시하는 alert 문구를 결과창에 기록 (기록 후 원래 alert 도 그대로 실행, 페이지 종료 시 원복)
    scwin.orgAlert = window.alert;
    window.alert = function (msg) {
        wf_body_bottom.getObj("scwin").setReturnValue("alert : " + msg);
        return scwin.orgAlert.apply(window, arguments);
    };

    // 정적 select1 은 초기 selectedIndex 가 적용되지 않으므로 기본값 명시 설정
    con_dateValidCheck.setValue("true");
    con_dateValidSet.setValue("true");
    con_invalidMessageFunc.setValue("scwin.target1_cal_returnMessage");

    // comp 초기 생성
    await scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// 페이지 종료 시 alert 후킹 원복
scwin.onpageunload = function () {
    if (scwin.orgAlert) {
        window.alert = scwin.orgAlert;
    }
};



// comp 생성
//  - cal : 검증 대상 Body Column (inputType="calendar" + dataType="date")
//          dateValidCheck / dateValidSet / invalidMessageFunc 는 con (미설정이면 속성 자체를 넣지 않음)
scwin.comp_init = async function () {
    // 기존 target / dataList / label 삭제
    if (typeof target1 !== 'undefined' && target1) {
        target1.remove();
    }
    if (typeof dlt_bind !== 'undefined' && dlt_bind) {
        $p.data.remove("dlt_bind");
    }
    if (typeof label1 !== 'undefined' && label1) {
        label1.remove();
    }

    // 테스트 정보 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[절차] cal 셀 클릭 -> 유효하지 않은 날짜(예: 20261345) 입력 -> 셀 밖(조건 영역) 클릭 -> 셀 값 확인\n[확인] 사용자 정의 함수 호출과 반환값, 표시된 alert 문구(결과창에도 기록), 셀 저장값"', '', 'label1');

    // dataList 생성 (calendar Column 바인딩 컬럼은 dataType="date")
    let strNameSpace = $c.gcm.getNameSpace();
    let strDlt = '';
    strDlt += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="cal" name="cal" dataType="date"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);
    dlt_bind.setJSON([
        { "cal" : "20261001" },
        { "cal" : "20261015" }
    ], false);

    // con 값 (미설정이면 속성 자체를 넣지 않는다)
    let properties = {
        dateValidCheck : con_dateValidCheck.getValue(),
        dateValidSet : con_dateValidSet.getValue(),
        invalidMessageFunc : con_invalidMessageFunc.getValue()
    };
    let cList = $c.gcm.createCList(properties);

    // target 생성
    let grp_comp = $c.gcm.getTestGroup();
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' dataList="data:dlt_bind" checkAllType="false" id="" style="width:300px;height:120px;">';
    strTarget += '<w2:caption style="" id="caption1" value="this is a grid caption."></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="260" style="" inputType="text" id="column1" value="cal"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="260" style="" id="cal" inputType="calendar" dataType="date" viewType="icon" calendarValueType="yearMonthDate" ' + cList + '></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin["target1"] = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
}



// validation 1, 2, 4 : 메시지 문자열 반환
scwin.target1_cal_returnMessage = function () {
    wf_body_bottom.getObj("scwin").setReturnValue("invalidMessageFunc 호출 -> 반환값 : " + scwin.returnMessage);
    return scwin.returnMessage;
}



// validation 1, 3 : 빈 문자열 반환
scwin.target1_cal_returnEmpty = function () {
    wf_body_bottom.getObj("scwin").setReturnValue("invalidMessageFunc 호출 -> 반환값 : ''");
    return "";
}



// validation 1, 3 : 반환 없음
scwin.target1_cal_returnNone = function () {
    wf_body_bottom.getObj("scwin").setReturnValue("invalidMessageFunc 호출 -> 반환값 없음");
}



// 셀 저장값 (전체 Row)
scwin.btn_getCellData_onclick = function (e) {
    let rowCnt = dlt_bind.getRowCount();
    for (let i = 0; i < rowCnt; i++) {
        wf_body_bottom.getObj("scwin").setReturnValue("Row " + i + " '" + dlt_bind.getCellData(i, "cal") + "'");
    }
}
